package dev.dangeroni.offhandfix.mixin;
import dev.dangeroni.offhandfix.OffhandRefill;import it.unimi.dsi.fastutil.ints.Int2ObjectMap;import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap;import java.util.ArrayList;import java.util.List;
import net.minecraft.client.MinecraftClient;import net.minecraft.client.network.ClientPlayNetworkHandler;import net.minecraft.client.network.ClientPlayerInteractionManager;import net.minecraft.entity.player.PlayerEntity;import net.minecraft.item.ItemStack;import net.minecraft.network.packet.c2s.play.ClickSlotC2SPacket;import net.minecraft.screen.ScreenHandler;import net.minecraft.screen.slot.Slot;import net.minecraft.screen.slot.SlotActionType;
import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.At;import org.spongepowered.asm.mixin.injection.Inject;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(ClientPlayerInteractionManager.class) abstract class MultiPlayerGameModeMixin {
 @Inject(method="clickSlot",at=@At("HEAD"),cancellable=true) private void offhandfix$mirrorQuickMoveRefillLocally(int syncId,int slotId,int button,SlotActionType actionType,PlayerEntity player,CallbackInfo ci){if(actionType!=SlotActionType.QUICK_MOVE)return;ScreenHandler menu=player.currentScreenHandler;if(syncId!=menu.syncId||slotId<0||slotId>=menu.slots.size())return;Slot slot=menu.getSlot(slotId);if(!slot.hasStack())return;ItemStack source=slot.getStack();if(OffhandRefill.calculateTransferAmount(player.getOffHandStack(),source)<=0)return;ClientPlayNetworkHandler connection=MinecraftClient.getInstance().getNetworkHandler();if(connection==null)return;List<ItemStack> previous=snapshot(menu);OffhandRefill.refillOffhand(player.getOffHandStack(),source);if(source.isEmpty())slot.setStack(ItemStack.EMPTY);else slot.markDirty();player.getInventory().markDirty();Int2ObjectMap<ItemStack> changes=changed(menu,previous);connection.sendPacket(new ClickSlotC2SPacket(syncId,menu.getRevision(),(short)slotId,(byte)button,actionType,menu.getCursorStack().copy(),changes));ci.cancel();}
 private List<ItemStack> snapshot(ScreenHandler menu){List<ItemStack> r=new ArrayList<>(menu.slots.size());for(Slot s:menu.slots)r.add(s.getStack().copy());return r;}private Int2ObjectMap<ItemStack> changed(ScreenHandler menu,List<ItemStack> p){Int2ObjectMap<ItemStack> r=new Int2ObjectOpenHashMap<>();for(int i=0;i<menu.slots.size();i++)if(!ItemStack.areEqual(p.get(i),menu.getSlot(i).getStack()))r.put(i,menu.getSlot(i).getStack().copy());return r;}
}
